package edu.pe.cibertec.saibm.membresia.infrastructure.persistence;
import java.time.Instant; import java.util.*; import org.springframework.beans.factory.ObjectProvider; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import com.fasterxml.jackson.databind.ObjectMapper; import com.fasterxml.jackson.databind.json.JsonMapper; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import edu.pe.cibertec.saibm.membresia.application.port.out.*; import edu.pe.cibertec.saibm.membresia.domain.event.MembershipEvent; import edu.pe.cibertec.saibm.membresia.domain.model.*;
@Component @Transactional public class MembershipPersistenceAdapter implements MembershipStorePort {private final PlanJpaRepository plans;private final AssignmentJpaRepository assignments;private final HistoryJpaRepository histories;private final OutboxJpaRepository outbox;private final ObjectMapper mapper;public MembershipPersistenceAdapter(PlanJpaRepository p,AssignmentJpaRepository a,HistoryJpaRepository h,OutboxJpaRepository o,ObjectProvider<ObjectMapper> m){plans=p;assignments=a;histories=h;outbox=o;mapper=m.getIfAvailable(()->JsonMapper.builder().addModule(new JavaTimeModule()).build());}public Optional<Plan> plan(UUID id){return plans.findById(id).map(PlanJpaEntity::domain);}public List<Plan> activePlans(Instant at){return plans.active(at).stream().map(PlanJpaEntity::domain).toList();}public Optional<MembershipAssignment> assignmentByKey(String k){return assignments.byKey(k).map(AssignmentJpaEntity::domain);}public Optional<MembershipAssignment> activeAssignment(String u,Instant at){return assignments.active(u,at).map(AssignmentJpaEntity::domain);}public int insert(MembershipAssignment a){var inserted=assignments.insert(a.id(),a.userId(),a.planId(),a.planCode(),a.planVersion(),a.reservationLimit(),a.validFrom(),a.validUntil(),a.idempotencyKey(),a.requestHash(),a.legacyUserId());assignments.flush();return inserted;}public void save(Plan p){plans.saveAndFlush(new PlanJpaEntity(p));}public void save(MembershipAssignment a){assignments.saveAndFlush(new AssignmentJpaEntity(a));}public void history(MembershipHistory h){histories.saveAndFlush(new HistoryJpaEntity(h));}public List<MembershipHistory> history(String u){return histories.findByUserIdOrderByOccurredAtDesc(u).stream().map(x->new MembershipHistory(x.id,x.userId,x.assignmentId,x.action,x.occurredAt,x.correlationId)).toList();}public List<MembershipAssignment> expiring(Instant at){return assignments.expiring(at).stream().map(AssignmentJpaEntity::domain).toList();}public void outbox(MembershipEvent e){try{outbox.saveAndFlush(new OutboxJpaEntity(e,mapper.writeValueAsString(e)));}catch(Exception x){throw new IllegalStateException("Cannot serialize membership event",x);}}}
